export interface HiCommunitySeedGroup {
  campaignId: string;
  source: SignalSource;
  signals: ExtractedSignal[];
}

/** HSEO 2022 statewide signals + Vibrant Hawaiʻi 2026 signals, grouped by source for ensureSeed. */
export function hiCommunitySeedGroups(): HiCommunitySeedGroup[] {
  const map = new Map<SignalSource, ExtractedSignal[]>();
  const add = (source: SignalSource, s: ExtractedSignal) => {
    const list = map.get(source) ?? [];
    list.push(s);
    map.set(source, list);
  };
  for (const { campaigns, source, ...signal } of HI_ENERGY_SIGNALS) {
    if (campaigns.includes('hi-energy-statewide')) add(source, signal);
  }
  for (const { campaigns: _c, source, ...signal } of VIBRANT_SIGNALS) add(source, signal);
  return [...map.entries()].map(([source, signals]) => ({ campaignId: HI_COMMUNITY_CAMPAIGN_ID, source, signals }));
}
